import React from 'react';
import { Container, Typography, Box, Button } from '@material-ui/core';
import { makeStyles } from '@material-ui/core/styles';
import { Link } from 'react-router-dom';

const useStyles = makeStyles((theme) => ({
  root: {
    minHeight: '100vh',
    paddingTop: theme.spacing(8),
    paddingBottom: theme.spacing(8),
    textAlign: 'center',
    background: 'linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%)',
    position: 'relative',
    overflow: 'hidden',
  },
  content: {
    position: 'relative',
    zIndex: 2,
    animation: '$fadeIn 0.8s ease-out',
  },
  title: {
    marginBottom: theme.spacing(4),
    fontWeight: 900,
    background: 'linear-gradient(45deg, #2196F3 30%, #21CBF3 90%)',
    WebkitBackgroundClip: 'text',
    WebkitTextFillColor: 'transparent',
    textShadow: '2px 2px 4px rgba(0,0,0,0.1)',
    animation: '$slideUp 0.8s ease-out',
  },
  subtitle: {
    marginBottom: theme.spacing(6),
    color: theme.palette.text.secondary,
    fontSize: '1.5rem',
    lineHeight: 1.6,
    fontWeight: 500,
    animation: '$slideUp 0.8s ease-out 0.2s',
    opacity: 0,
    animationFillMode: 'forwards',
  },
  loginButton: {
    marginTop: theme.spacing(4),
    padding: theme.spacing(2, 6),
    fontSize: '1.3rem',
    borderRadius: 30,
    background: 'linear-gradient(45deg, #2196F3 30%, #21CBF3 90%)',
    boxShadow: '0 3px 15px rgba(33, 203, 243, 0.3)',
    transition: 'all 0.3s ease',
    animation: '$slideUp 0.8s ease-out 0.4s',
    opacity: 0,
    animationFillMode: 'forwards',
    '&:hover': {
      transform: 'translateY(-3px)',
      boxShadow: '0 5px 20px rgba(33, 203, 243, 0.5)',
    },
  },
  decorCircle: {
    position: 'absolute',
    borderRadius: '50%',
    background: 'linear-gradient(45deg, #2196F3 30%, #21CBF3 90%)',
    opacity: 0.1,
    animation: '$float 5s ease-in-out infinite',
  },
  '@keyframes fadeIn': {
    '0%': {
      opacity: 0,
    },
    '100%': {
      opacity: 1,
    },
  },
  '@keyframes slideUp': {
    '0%': {
      opacity: 0,
      transform: 'translateY(20px)',
    },
    '100%': {
      opacity: 1,
      transform: 'translateY(0)',
    },
  },
  '@keyframes float': {
    '0%, 100%': {
      transform: 'translateY(0) rotate(0deg)',
    },
    '50%': {
      transform: 'translateY(-20px) rotate(10deg)',
    },
  },
}));

function Home() {
  const classes = useStyles();

  return (
    <Container className={classes.root} maxWidth={false}>
      {[...Array(5)].map((_, i) => (
        <Box
          key={i}
          className={classes.decorCircle}
          style={{
            width: `${Math.random() * 200 + 100}px`,
            height: `${Math.random() * 200 + 100}px`,
            left: `${Math.random() * 100}%`,
            top: `${Math.random() * 100}%`,
          }}
        />
      ))}

      <Box className={classes.content} maxWidth={800} mx="auto">
        <Typography variant="h2" className={classes.title}>
          Welcome to Dynonary English
        </Typography>

        <Typography variant="h5" className={classes.subtitle}>
          Your personal English learning companion. Improve your vocabulary, practice pronunciation, 
          and master the English language with our interactive tools.
        </Typography>

        <Button
          component={Link}
          to="/login"
          variant="contained"
          color="primary"
          size="large"
          className={classes.loginButton}
        >
          Login to Start Learning
        </Button>
      </Box>
    </Container>
  );
}

export default Home;
